const resultsLoader=document.getElementById("results-loader"),resultsList=document.getElementById("results-list");var InsLocatorServices=function(){const apiUrl="",request=axios.create({});let config_headers={"Content-Type":"application/json",Accept:"application/json","X-CSRF-TOKEN":document.querySelector('[name="csrf-token"]').value};async function processRequest(method,url,payload,headers=config_headers){let endpoint=""+url,process="get"===method.toLowerCase()?request.get(endpoint,{headers:headers}):request[method](endpoint,payload,{headers:headers});return await process.then(response=>response.data.errors&&("object"!=typeof response.data.errors||Object.keys(response.data.errors).length)?(console.error(`API Error: ${url}`,response.data.errors),{state:!1,data:response.data}):{state:!0,data:response.data}).catch(error=>(error.response.data&&error.response.data.errors&&console.error(`API Error: ${url}`,error.response.data.errors),{state:!1,data:error.response.data}))}return{searchLocations:async function(filter){resultsList.style.display="none",resultsLoader.style.display="block";let url=`/api/locator/locations?page=${filter.page}&size=${filter.size}`;return url+=`&lat=${filter.location.lat}&lng=${filter.location.lng}`,url+=`&distance=${filter.distance}`,url+=`&system_fields=${filter.system_fields}`,await processRequest("get",url)},processRequest:processRequest}}();